"""Shared pytest configuration for the cynthus-mocks/chat (Chat mock) test suite.

Mirrors the container's runtime layout (PYTHONPATH=/opt/app/shared/src:/opt/app/src) so that
`import chat` and `import cynthus...` resolve the way they do under Docker.
"""

# Generated by tools/generate_service_tests.py - edit the generator, not this file.

import ast
import os
import sys
import types
from pathlib import Path

import pytest

PACKAGE = 'chat'
CONTAINER_DIR = Path(__file__).resolve().parents[1]
SRC_DIR = CONTAINER_DIR / 'src'
MESSAGING_CORE_SRC = Path(
    os.environ.get('CYNTHUS_MESSAGING_CORE_SRC')
    or Path(__file__).resolve().parents[4] / 'cynthus-messaging-core' / 'src'
)

for _path in (SRC_DIR, MESSAGING_CORE_SRC):
    if _path.exists() and str(_path) not in sys.path:
        sys.path.insert(0, str(_path))

# The services read their configuration from the environment when they are imported.
os.environ.update({
    'CACHE_DRIVER': 'redis',
    'CACHE_HOST': 'cache.test',
    'CACHE_PORT': '6379',
    'CACHE_USERNAME': 'svc',
    'CACHE_PASSWORD': 'secret',
    'SERVICE_BUS_NAMESPACE': 'bus.test.servicebus.windows.net',
})

CACHE_URL = 'redis://svc:secret@cache.test:6379/0'

MESSAGING_IS_FAKED = False
AZURE_IS_FAKED = False


def _module_parses(dotted_name):
    """Return True when the named module's source compiles."""

    base = SRC_DIR.joinpath(*dotted_name.split('.'))
    path = base / '__init__.py' if base.is_dir() else base.with_suffix('.py')

    try:
        ast.parse(path.read_text(encoding='utf-8'))
    except SyntaxError:
        return False

    return True


# A package whose __init__.py does not compile would make every submodule unimportable, which hides
# the (healthy) routes behind the entry point's defect. Register an empty stand-in package instead so
# the routes can still be unit tested; the entry point itself is covered by its own (xfail) tests.
if not _module_parses(PACKAGE):
    _stub = types.ModuleType(PACKAGE)
    _stub.__path__ = [str(SRC_DIR / PACKAGE)]
    _stub.__file__ = str(SRC_DIR / PACKAGE / '__init__.py')
    sys.modules[PACKAGE] = _stub



@pytest.fixture
def cache_url():
    return CACHE_URL


@pytest.fixture
def module_parses():
    return _module_parses


@pytest.fixture
def messaging_is_faked():
    return MESSAGING_IS_FAKED


@pytest.fixture
def azure_is_faked():
    return AZURE_IS_FAKED
